import tkinter as tk
from tkinter import ttk, filedialog, messagebox, colorchooser
import json, os, re, random, html, struct, zlib, base64, pathlib, unicodedata
DATA=json.loads(zlib.decompress(base64.b64decode(PACKED)))
FONTS=DATA['fonts']; FORMS=DATA['forms']; ATLAS=DATA['atlas']
MARKS={'Unicode':'█','ASCII':'#','Money':'$','Shade':'▓','Dots':'•','Binary':'1','Custom':'@'}
def shape(s):
    # Contextual joining for common Arabic letters, with simple RTL run ordering.
    def run(m):
        a=list(m.group()); out=[]
        for i,c in enumerate(a):
            f=FORMS.get(c,{})
            p=FORMS.get(a[i-1],{}) if i else {}; n=FORMS.get(a[i+1],{}) if i+1<len(a) else {}
            before=('initial' in p or 'medial' in p) and ('final' in f or 'medial' in f)
            after=('initial' in f or 'medial' in f) and ('final' in n or 'medial' in n)
            out.append(f.get('medial' if before and after else 'final' if before else 'initial' if after else 'isolated',c))
        return ''.join(reversed(out))
    return re.sub(r'[\u0621-\u064a\u0671-\u06d3]+(?: +[\u0621-\u064a\u0671-\u06d3]+)*',run,s)
def parse_fig(raw):
    lines=raw.splitlines(); h=lines[0].split(); magic=h[0]
    if not magic.startswith(('flf2a','tlf2a')) or len(magic)!=6: raise ValueError('Invalid FLF/TLF header')
    hard=magic[-1]; height=int(h[1]); comments=int(h[5]); pos=1+comments
    if not 1<=height<=100 or comments<0: raise ValueError('Invalid font dimensions')
    glyph={}
    def read(c):
        nonlocal pos
        if pos+height>len(lines): raise ValueError('Truncated font')
        rows=lines[pos:pos+height]; pos+=height; end=rows[0][-1:] or '@'; glyph[c]=[r.removesuffix(end).removesuffix(end).replace(hard,' ') for r in rows]
    for n in range(32,127): read(chr(n))
    # Standard optional German characters, then tagged code points.
    for c in 'ÄÖÜäöüß':
        if pos>=len(lines) or re.match(r'^\s*(?:0x[0-9a-fA-F]+|[0-9]+)\s',lines[pos]): break
        read(c)
    while pos<len(lines):
        tag=lines[pos].split(); pos+=1
        if not tag: continue
        try: n=int(tag[0],0) if not re.match(r'^0[0-7]+$',tag[0]) else int(tag[0],8); c=chr(n)
        except (ValueError,OverflowError): break
        read(c)
    return ['FIGlet / TOIlet import',glyph]
def render(text,name,mode='Unicode',custom='@',gap=1,scale=1,shadow=False,frame=False,mirror=False,rotation=0):
    cat,glyph=FONTS[name]; mark=(custom or '@')[0] if mode=='Custom' else MARKS.get(mode,'█'); allrows=[]
    if cat=='Arabic': text=shape(text)
    for line in text[:120].split('\n'):
        gs=[glyph.get(c,glyph.get('?')) for c in line]; gs=[g for g in gs if g]; height=len(next(iter(glyph.values())))
        for y in range(height):
            row=(' '*gap).join((g[y] if cat.startswith('FIGlet') else ''.join(mark if x=='1' else ' ' for x in g[y])) for g in gs)
            row=''.join(c*scale for c in row); allrows.extend([row]*scale)
        allrows.append('')
    a=allrows[:-1] or ['']; w=max(map(len,a),default=0); a=[r.ljust(w) for r in a]
    if not cat.startswith('FIGlet'):
        while len(a)>1 and not a[0].strip(): a.pop(0)
        while len(a)>1 and not a[-1].strip(): a.pop()
    if shadow:
        b=[list(' '*(w+1)) for _ in range(len(a)+1)]
        for y,r in enumerate(a):
            for x,c in enumerate(r):
                if c!=' ': b[y+1][x+1]='░' if mode!='ASCII' else '.'
        for y,r in enumerate(a):
            for x,c in enumerate(r):
                if c!=' ': b[y][x]=c
        a=[''.join(r) for r in b]; w+=1
    if frame: a=['┌'+'─'*(w+2)+'┐']+['│ '+r+' │' for r in a]+['└'+'─'*(w+2)+'┘']
    if mirror: a=[r[::-1] for r in a]
    for _ in range(rotation//90): a=[''.join(x) for x in zip(*a[::-1])] if a and a[0] else a
    return '\n'.join(a)
def rgb(s): return tuple(bytes.fromhex(s.lstrip('#')))
def color_at(y,n,c1,c2): return tuple(round(a+(b-a)*y/max(1,n-1)) for a,b in zip(rgb(c1),rgb(c2)))
def svg(text,c1,c2):
    rows=text.split('\n'); w=max(map(len,rows),default=1)*9+20; h=len(rows)*18+20
    return f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}"><rect width="100%" height="100%" fill="#0b1020"/><g font-family="monospace" font-size="14" xml:space="preserve">'+''.join(f'<text x="10" y="{24+i*18}" fill="#{bytes(color_at(i,len(rows),c1,c2)).hex()}">{html.escape(r)}</text>' for i,r in enumerate(rows))+'</g></svg>'
def ansi(text,c1,c2):
    rows=text.split('\n'); return '\n'.join('\x1b[38;2;%d;%d;%dm'%color_at(i,len(rows),c1,c2)+r+'\x1b[0m' for i,r in enumerate(rows))
def png(text,c1,c2):
    rows=text.split('\n'); w=max(1,max(map(len,rows),default=1))*9+20; h=len(rows)*18+20
    if w*h>18_000_000: raise ValueError('Image too large; reduce text or scale')
    bg=bytes((11,16,32)); pixels=[bytearray(bg*w) for _ in range(h)]
    for y,row in enumerate(rows):
        col=bytes(color_at(y,len(rows),c1,c2))
        for x,c in enumerate(row):
            for j,r in enumerate(ATLAS.get(c,ATLAS['?'])):
                for k,v in enumerate(r):
                    if v=='1': pos=(10+x*9+k)*3; pixels[10+y*18+j][pos:pos+3]=col
    def chunk(t,d): return struct.pack('>I',len(d))+t+d+struct.pack('>I',zlib.crc32(t+d)&0xffffffff)
    return b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>2I5B',w,h,8,2,0,0,0))+chunk(b'IDAT',zlib.compress(b''.join(b'\0'+r for r in pixels)))+chunk(b'IEND',b'')
def main():
    root=tk.Tk(); root.title('LeerBox | Text Art Studio 2.0'); root.geometry('1200x800'); root.minsize(850,550)
    style=ttk.Style(root); style.theme_use('clam'); style.configure('.',background='#182235',foreground='#e4edff'); style.configure('TButton',background='#263650'); style.configure('TEntry',fieldbackground='#e4edff',foreground='#101828'); style.configure('TCombobox',fieldbackground='#e4edff',foreground='#101828'); root.configure(bg='#101828')
    top=ttk.Frame(root,padding=10); top.pack(fill='x'); ttk.Label(top,text='LEERBOX  /  TEXT ART STUDIO 2.0',font=('Segoe UI',20,'bold')).pack(anchor='w'); ttk.Label(top,text=f'{len(FONTS)} raster typefaces • FLF/TLF import • offline').pack(anchor='w')
    src=tk.Text(top,height=2,font=('Segoe UI',14),bg='#0b1020',fg='white',insertbackground='white'); src.pack(fill='x',pady=8); src.insert('1.0','LeerBox')
    bar=ttk.Frame(top); bar.pack(fill='x'); vars={k:tk.StringVar(value=v) for k,v in [('Search',''),('Category','All'),('Mode','Unicode'),('Gap','1'),('Scale','1'),('Rotation','0'),('Custom','@')]}; checks={k:tk.BooleanVar() for k in ['Shadow','Frame','Mirror','Favorites']}; colors=['#63e6d5','#8c9bff']; current=[next(iter(FONTS))]; fav=set(); pref=pathlib.Path.home()/'.leerbox_art_favorites.json'
    try: fav.update(json.loads(pref.read_text()))
    except Exception: pass
    for k,vals in [('Search',None),('Category',['All','Sans','Serif','Mono','Arabic','FIGlet / TOIlet import']),('Mode',list(MARKS)),('Gap',['0','1','2','3']),('Scale',['1','2']),('Rotation',['0','90','180','270']),('Custom',None)]:
        box=ttk.Frame(bar); box.pack(side='left',padx=4); ttk.Label(box,text=k).pack(anchor='w'); widget=ttk.Combobox(box,textvariable=vars[k],values=vals,state='readonly',width=15 if k=='Category' else 9) if vals else ttk.Entry(box,textvariable=vars[k],width=14 if k=='Search' else 5); widget.pack()
    controls=ttk.Frame(top); controls.pack(fill='x',pady=7)
    for k,v in checks.items(): ttk.Checkbutton(controls,text=k,variable=v).pack(side='left')
    panel=ttk.Panedwindow(root,orient='horizontal'); panel.pack(fill='both',expand=True,padx=10,pady=5); left=ttk.Frame(panel); right=ttk.Frame(panel); panel.add(left,weight=1); panel.add(right,weight=4)
    lb=tk.Listbox(left,bg='#0b1020',fg='#e4edff',selectbackground='#395789',exportselection=False); lb.pack(side='left',fill='both',expand=True); sy=ttk.Scrollbar(left,command=lb.yview); sy.pack(side='right',fill='y'); lb.configure(yscrollcommand=sy.set)
    out=tk.Text(right,bg='#0b1020',fg=colors[0],font=('Consolas',10),wrap='none'); out.grid(row=0,column=0,sticky='nsew'); sy=ttk.Scrollbar(right,command=out.yview); sy.grid(row=0,column=1,sticky='ns'); sx=ttk.Scrollbar(right,orient='horizontal',command=out.xview); sx.grid(row=1,column=0,sticky='ew'); out.configure(yscrollcommand=sy.set,xscrollcommand=sx.set); right.rowconfigure(0,weight=1); right.columnconfigure(0,weight=1)
    status=tk.StringVar(); ttk.Label(root,textvariable=status).pack(anchor='w',padx=10); actions=ttk.Frame(root,padding=10); actions.pack(fill='x'); names=[]; result=['']; job=[None]
    def make(n): return render(src.get('1.0','end-1c'),n,vars['Mode'].get(),vars['Custom'].get(),int(vars['Gap'].get()),int(vars['Scale'].get()),checks['Shadow'].get(),checks['Frame'].get(),checks['Mirror'].get(),int(vars['Rotation'].get()))
    def show():
        if current[0] not in FONTS:return
        result[0]=make(current[0]); out.configure(state='normal'); out.delete('1.0','end'); out.insert('1.0',result[0]); rows=result[0].split('\n')
        for i in range(len(rows)):
            tag=f'line{i}'; out.tag_configure(tag,foreground='#'+bytes(color_at(i,len(rows),*colors)).hex()); out.tag_add(tag,f'{i+1}.0',f'{i+1}.end')
        out.configure(state='disabled'); status.set(f'{len(names)} fonts | {current[0]} | input max 120 characters')
    def refresh(*_):
        names[:]=[n for n,(cat,_) in FONTS.items() if vars['Search'].get().lower() in n.lower() and (vars['Category'].get() in ('All',cat)) and (not checks['Favorites'].get() or n in fav)]; lb.delete(0,'end')
        for n in names: lb.insert('end',('★ ' if n in fav else '')+n)
        if names:
            if current[0] not in names: current[0]=names[0]
            i=names.index(current[0]); lb.selection_set(i); lb.see(i); show()
        else: status.set('No matching fonts')
    def select(_=None):
        if lb.curselection(): current[0]=names[lb.curselection()[0]]; show()
    lb.bind('<<ListboxSelect>>',select)
    def change(*_):
        if job[0]: root.after_cancel(job[0])
        job[0]=root.after(120,refresh)
    for v in list(vars.values())+list(checks.values()): v.trace_add('write',change)
    src.bind('<KeyRelease>',change)
    def favorite():
        n=current[0]; fav.symmetric_difference_update({n})
        try: pref.write_text(json.dumps(sorted(fav)))
        except OSError: pass
        refresh()
    def import_fonts():
        for path in filedialog.askopenfilenames(filetypes=[('FIGlet fonts','*.flf *.tlf'),('All files','*')]):
            try:
                raw=pathlib.Path(path).read_bytes(); FONTS[pathlib.Path(path).stem+' [import]']=parse_fig(raw.decode('utf-8-sig',errors='replace'))
            except Exception as e: messagebox.showerror('Import',str(e))
        vars['Category'].set('FIGlet / TOIlet import'); refresh()
    def pick(i):
        c=colorchooser.askcolor(colors[i])[1]
        if c: colors[i]=c; show()
    def randomize():
        if names: current[0]=random.choice(names); refresh()
    def gallery():
        win=tk.Toplevel(root); win.title('All matching fonts'); win.geometry('1000x700'); t=tk.Text(win,wrap='none',bg='#0b1020',fg=colors[0],font=('Consolas',8)); t.pack(side='left',fill='both',expand=True); s=ttk.Scrollbar(win,command=t.yview); s.pack(side='right',fill='y'); t.configure(yscrollcommand=s.set)
        for n in names: t.insert('end',n+'\n'+make(n)+'\n\n')
        t.configure(state='disabled')
    def export(ext):
        path=filedialog.asksaveasfilename(defaultextension='.'+ext,filetypes=[(ext.upper(),'*.'+ext)])
        if not path:return
        try:
            r=result[0]; v={'txt':lambda:r,'ansi':lambda:ansi(r,*colors),'svg':lambda:svg(r,*colors),'html':lambda:'<!doctype html><meta charset="utf-8">'+svg(r,*colors),'png':lambda:png(r,*colors)}[ext](); pathlib.Path(path).write_bytes(v if isinstance(v,bytes) else v.encode('utf-8')); status.set('Saved '+path)
        except Exception as e: messagebox.showerror('Export',str(e))
    def copy(): root.clipboard_clear(); root.clipboard_append(result[0]); status.set('Copied')
    for label,cmd in [('Copy',copy),('★ Favorite',favorite),('Random',randomize),('Gallery',gallery),('Import FLF/TLF',import_fonts),('Color 1',lambda:pick(0)),('Color 2',lambda:pick(1))]+[(x.upper(),lambda x=x:export(x)) for x in ['txt','ansi','html','svg','png']]: ttk.Button(actions,text=label,command=cmd,width=10 if len(label)<10 else 14).pack(side='left',padx=2)
    refresh(); root.mainloop()
if __name__=='__main__': main()
